/**
 * Testbench for GraphSAGE QAT v2 HLS Implementation
 *
 * Loads test vectors generated by tests/generate_test_vectors_qat_v2.py
 * and compares the HLS output against the Python integer-only reference.
 *
 * Expected result: 0 LSB max error (bit-exact match with Python emulator).
 *
 * File layout (relative to csim build dir):
 *   build/hls/graphsage_qat_v2/solution1/csim/build/
 *   ← 6 levels up → project root
 */

#include <cmath>
#include <cstdlib>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>

#include "graphsage_layer_qat_v2.h"
#include "graphsage_layer_qat_v2.cpp"

// ============================================================================
// Paths (relative to csim build dir)
// ============================================================================

static const char* WEIGHTS_DIR    = "../../../../../../build/weights_qat_v2/";
static const char* TESTVEC_DIR    = "../../../../../../build/test_vectors_qat_v2/";

// ============================================================================
// I/O helpers
// ============================================================================

template<typename T>
static void load_1d(const char* path, T* arr, int n) {
    std::ifstream f(path);
    if (!f.is_open()) {
        std::cerr << "ERROR: cannot open " << path << std::endl;
        exit(1);
    }
    for (int i = 0; i < n; i++) {
        int v; f >> v; arr[i] = (T)v;
    }
    std::cout << "  loaded " << path << " (" << n << " elements)" << std::endl;
}

template<typename T>
static void load_2d(const char* path, T* arr, int rows, int cols) {
    std::ifstream f(path);
    if (!f.is_open()) {
        std::cerr << "ERROR: cannot open " << path << std::endl;
        exit(1);
    }
    for (int i = 0; i < rows; i++)
        for (int j = 0; j < cols; j++) {
            int v; f >> v; arr[i * cols + j] = (T)v;
        }
    std::cout << "  loaded " << path << " (" << rows << "x" << cols << ")" << std::endl;
}

static void load_adj(const char* path, qv2_adj_t adj[NUM_NODES][NUM_NODES]) {
    std::ifstream f(path);
    if (!f.is_open()) {
        std::cerr << "ERROR: cannot open " << path << std::endl;
        exit(1);
    }
    for (int i = 0; i < NUM_NODES; i++)
        for (int j = 0; j < NUM_NODES; j++) {
            int v; f >> v; adj[i][j] = (qv2_adj_t)v;
        }
    std::cout << "  loaded " << path << " (" << NUM_NODES << "x" << NUM_NODES << ")" << std::endl;
}

// Read a single integer value from a key:value config file
static int read_config_int(const char* path, const char* key) {
    std::ifstream f(path);
    if (!f.is_open()) {
        std::cerr << "ERROR: cannot open " << path << std::endl;
        exit(1);
    }
    std::string line;
    while (std::getline(f, line)) {
        size_t colon = line.find(':');
        if (colon == std::string::npos) continue;
        std::string k = line.substr(0, colon);
        // trim spaces
        while (!k.empty() && k.back() == ' ') k.pop_back();
        if (k == key) {
            std::istringstream ss(line.substr(colon + 1));
            int v; ss >> v;
            return v;
        }
    }
    std::cerr << "ERROR: key '" << key << "' not found in " << path << std::endl;
    exit(1);
}

// ============================================================================
// Main testbench
// ============================================================================

int main() {
    std::cout << "============================================================" << std::endl;
    std::cout << "     GraphSAGE QAT v2 HLS Testbench" << std::endl;
    std::cout << "============================================================" << std::endl;
    std::cout << std::endl;
    std::cout << "Configuration:" << std::endl;
    std::cout << "  NUM_NODES       = " << NUM_NODES       << std::endl;
    std::cout << "  IN_FEATURES     = " << IN_FEATURES     << std::endl;
    std::cout << "  HIDDEN_FEATURES = " << HIDDEN_FEATURES << std::endl;
    std::cout << "  OUT_FEATURES    = " << OUT_FEATURES    << std::endl;
    std::cout << "  M_BITS          = " << M_BITS          << std::endl;
    std::cout << "  K_BITS          = " << K_BITS          << "  (K=" << (1 << K_BITS) << ")" << std::endl;
    std::cout << std::endl;

    // ------------------------------------------------------------------ //
    // Declare arrays
    // ------------------------------------------------------------------ //
    qv2_adj_t    adj_matrix[NUM_NODES][NUM_NODES];
    qv2_data_t   input     [NUM_NODES][IN_FEATURES];
    qv2_weight_t weights1  [HIDDEN_FEATURES][IN_FEATURES];
    qv2_bias_t   bias1     [HIDDEN_FEATURES];
    qv2_weight_t weights2  [OUT_FEATURES][HIDDEN_FEATURES];
    qv2_bias_t   bias2     [OUT_FEATURES];
    qv2_data_t   output    [NUM_NODES][OUT_FEATURES];
    qv2_data_t   reference [NUM_NODES][OUT_FEATURES];

    qv2_scale_fp_t beta1_fp, beta2_fp, eff_scale1_fp, eff_scale2_fp;

    // ------------------------------------------------------------------ //
    // Load test vectors
    // ------------------------------------------------------------------ //
    std::cout << "Loading test vectors ..." << std::endl;

    std::string adj_path  = std::string(TESTVEC_DIR) + "adj_matrix_int16.txt";
    std::string inp_path  = std::string(TESTVEC_DIR) + "network_input_int8.txt";
    std::string w1_path   = std::string(TESTVEC_DIR) + "weights_layer1_int8.txt";
    std::string w2_path   = std::string(TESTVEC_DIR) + "weights_layer2_int8.txt";
    std::string b1_path   = std::string(TESTVEC_DIR) + "bias_layer1_int32.txt";
    std::string b2_path   = std::string(TESTVEC_DIR) + "bias_layer2_int32.txt";
    std::string ref_path  = std::string(TESTVEC_DIR) + "network_output_int8_reference.txt";
    std::string cfg_path  = std::string(TESTVEC_DIR) + "int8_config.txt";

    load_adj(adj_path.c_str(), adj_matrix);
    load_2d(inp_path.c_str(), (qv2_data_t*)input,    NUM_NODES,       IN_FEATURES);
    load_2d(w1_path.c_str(),  (qv2_weight_t*)weights1, HIDDEN_FEATURES, IN_FEATURES);
    load_2d(w2_path.c_str(),  (qv2_weight_t*)weights2, OUT_FEATURES,    HIDDEN_FEATURES);
    load_1d(b1_path.c_str(),  bias1,   HIDDEN_FEATURES);
    load_1d(b2_path.c_str(),  bias2,   OUT_FEATURES);
    load_2d(ref_path.c_str(), (qv2_data_t*)reference, NUM_NODES, OUT_FEATURES);

    // ------------------------------------------------------------------ //
    // Load scale parameters from config file
    // ------------------------------------------------------------------ //
    std::cout << std::endl << "Loading fixed-point parameters ..." << std::endl;
    beta1_fp      = (qv2_scale_fp_t)read_config_int(cfg_path.c_str(), "beta1_fp");
    beta2_fp      = (qv2_scale_fp_t)read_config_int(cfg_path.c_str(), "beta2_fp");
    eff_scale1_fp = (qv2_scale_fp_t)read_config_int(cfg_path.c_str(), "eff_scale1_fp");
    eff_scale2_fp = (qv2_scale_fp_t)read_config_int(cfg_path.c_str(), "eff_scale2_fp");

    std::cout << "  beta1_fp      = " << (int)beta1_fp      << std::endl;
    std::cout << "  beta2_fp      = " << (int)beta2_fp      << std::endl;
    std::cout << "  eff_scale1_fp = " << (int)eff_scale1_fp << std::endl;
    std::cout << "  eff_scale2_fp = " << (int)eff_scale2_fp << std::endl;

    // ------------------------------------------------------------------ //
    // Print input sample
    // ------------------------------------------------------------------ //
    std::cout << std::endl << "Input (node 0): [";
    for (int f = 0; f < IN_FEATURES; f++) {
        std::cout << (int)input[0][f];
        if (f < IN_FEATURES - 1) std::cout << ", ";
    }
    std::cout << "]" << std::endl;

    // ------------------------------------------------------------------ //
    // Run HLS function
    // ------------------------------------------------------------------ //
    std::cout << std::endl
              << "============================================================" << std::endl;
    std::cout << "Running graphsage_qat_v2 ..." << std::endl;
    std::cout << "============================================================" << std::endl;

    graphsage_qat_v2(
        adj_matrix, input,
        weights1, bias1,
        weights2, bias2,
        output,
        beta1_fp, beta2_fp,
        eff_scale1_fp, eff_scale2_fp
    );

    // ------------------------------------------------------------------ //
    // Compare vs Python reference
    // ------------------------------------------------------------------ //
    std::cout << std::endl
              << "============================================================" << std::endl;
    std::cout << "HLS output vs Python QAT v2 integer reference" << std::endl;
    std::cout << "============================================================" << std::endl;

    int max_error    = 0;
    int total_errors = 0;
    int total_elems  = NUM_NODES * OUT_FEATURES;

    for (int n = 0; n < NUM_NODES; n++) {
        std::cout << "Node " << n << ":" << std::endl;

        std::cout << "  HLS:  [";
        for (int o = 0; o < OUT_FEATURES; o++) {
            std::cout << std::setw(5) << (int)output[n][o];
            if (o < OUT_FEATURES - 1) std::cout << ",";
        }
        std::cout << " ]" << std::endl;

        std::cout << "  Ref:  [";
        for (int o = 0; o < OUT_FEATURES; o++) {
            std::cout << std::setw(5) << (int)reference[n][o];
            if (o < OUT_FEATURES - 1) std::cout << ",";
        }
        std::cout << " ]" << std::endl;

        std::cout << "  Diff: [";
        for (int o = 0; o < OUT_FEATURES; o++) {
            int diff = (int)output[n][o] - (int)reference[n][o];
            std::cout << std::setw(5) << diff;
            if (o < OUT_FEATURES - 1) std::cout << ",";
            if (diff != 0) total_errors++;
            if (std::abs(diff) > max_error) max_error = std::abs(diff);
        }
        std::cout << " ]" << std::endl;
    }

    // ------------------------------------------------------------------ //
    // Summary
    // ------------------------------------------------------------------ //
    std::cout << std::endl
              << "============================================================" << std::endl;
    std::cout << "SUMMARY" << std::endl;
    std::cout << "============================================================" << std::endl;
    std::cout << "Max error    : " << max_error    << " LSB" << std::endl;
    std::cout << "Total errors : " << total_errors << " / " << total_elems << std::endl;

    if (max_error == 0) {
        std::cout << std::endl
                  << "*** PERFECT MATCH — HLS matches Python QAT v2 exactly. ***" << std::endl;
        return 0;
    } else if (max_error <= 1) {
        std::cout << std::endl
                  << "*** EXCELLENT — max 1 LSB (rounding artefact). ***" << std::endl;
        return 0;
    } else {
        std::cout << std::endl
                  << "*** WARNING — errors exceed expected tolerance. ***" << std::endl;
        return 1;
    }
}
